{
  "table": "sensor_readings",
  "columns": [
    {
      "target": "device_id",
      "source": [
        "dev"
      ],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Device serial number, already upper case in source"
    },
    {
      "target": "read_at",
      "source": [
        "ts"
      ],
      "transform": "datetime",
      "params": {
        "format": "%Y-%m-%dT%H:%M:%SZ"
      },
      "confidence": 1.0,
      "note": "UTC timestamp in ISO format"
    },
    {
      "target": "temperature_c",
      "source": [
        "payload.t"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Air temperature in degrees Celsius"
    },
    {
      "target": "humidity_pct",
      "source": [
        "payload.h"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Relative humidity percentage"
    },
    {
      "target": "battery_v",
      "source": [
        "payload.bat_mv"
      ],
      "transform": "number",
      "params": {
        "decimal": ".",
        "factor": 0.001
      },
      "confidence": 1.0,
      "note": "Convert millivolts to volts"
    }
  ],
  "ignore": {},
  "review": []
}
